{
  const [value, setValue] = React.useState<string | null>("apples");
  return (
    <Box gap="$sm">
      <Accordion
        {...args}
        value={value}
        onChange={(next) => setValue(Array.isArray(next) ? (next[0] ?? null) : next)}
      >
        <Items />
      </Accordion>
      <Text fontSize={12} color="$color11">
        open: {value ?? "—"}
      </Text>
    </Box>
  );
}

