  render: (args) => {
    const [value, setValue] = React.useState<FileInputValue>(null);
    const resetRef = React.useRef<() => void>(null);

    const handleClear = () => {
      setValue(null);
      resetRef.current?.();
    };

    return (
      <Box flexDirection="column" gap="$md" width={320}>
        <FileInput
          {...args}
          value={value}
          onChange={setValue}
          resetRef={resetRef}
          placeholder="Pick a file"
          clearable
          label="Controlled file input"
