  render: () => (
    <Box flexDirection="row">
      {WEEK.map((date, index) => {
        const first = index === 0;
        const last = index === WEEK.length - 1;
        return (
          <Day
            key={date}
            date={date}
            inRange
            firstInRange={first}
            lastInRange={last}
            selected={first || last}
          />
        );
      })}
    </Box>
  ),
};

