CustomEffect.full:
export const CustomEffect: Story = {
  render: () => (
    <Stage>
      <SwipeDeck
        data={PEOPLE}
        renderCard={renderCard}
        keyExtractor={(p) => p.name}
        effect={(s) => {
          "worklet";
          if (s.isTop) {
            const tilt = (s.size.width > 0 ? s.drag.x / s.size.width : 0) * 18;
            return {
              transform: [
                { perspective: 1000 },
                { translateX: s.drag.x },
                { translateY: s.drag.y },
                { rotateZ: `${tilt}deg` },
              ],
              zIndex: 100,
            };
          }
          const d = Math.max(0, s.depth);
          return {
            transform: [
              { perspective: 1000 },
              { translateY: d * 24 },
              { rotateX: `${d * 12}deg` },
              { scale: 1 - d * 0.08 },
            ],
            opacity: 1 - d * 0.15,
            zIndex: Math.round(100 - d * 10),
          };
        }}
        stampLabels={{ right: "LIKE", left: "NOPE" }}
        style={{ flex: 1 }}
      />
    </Stage>
  ),
};

