{
  const target = useSharedValue<number[]>(new Array<number>(48).fill(0));
  React.useEffect(() => {
    let raf = 0;
    let mounted = true;
    const start = now();
    const tick = (): void => {
      if (!mounted) return;
      target.value = sample("sine", 48, (now() - start) / 1000);
      raf = requestAnimationFrame(tick);
    };
    tick();
    return () => {
      mounted = false;
      if (raf) cancelAnimationFrame(raf);
    };
  }, [target]);
  return (
    <Box width={360} maxWidth="100%">
      <AudioVisualizer {...args} count={48} target={target} />
    </Box>
  );
}

TargetSharedValue.full:
export const TargetSharedValue: Story = {
  render: (args) => {
    const target = useSharedValue<number[]>(new Array<number>(48).fill(0));
    React.useEffect(() => {
      let raf = 0;
      let mounted = true;
      const start = now();
      const tick = (): void => {
        if (!mounted) return;
        target.value = sample("sine", 48, (now() - start) / 1000);
        raf = requestAnimationFrame(tick);
      };
      tick();
      return () => {
        mounted = false;
        if (raf) cancelAnimationFrame(raf);
      };
    }, [target]);
    return (
      <Box width={360} maxWidth="100%">
        <AudioVisualizer {...args} count={48} target={target} />
      </Box>
    );
  },
  args: { variant: "mirror", gradient: ["#22d3ee", "#6366f1", "#ec4899"] },
};

