export const TenThousandClustered: Story = {
  args: { id: "pin", svg: PIN, width: 24, height: 24 },
  render: () => (
    <Map mapStyle={STREETS_STYLE}>
      <Camera initialViewState={{ center: EUROPE_CENTER, zoom: 4 }} />
      <SvgImage id="pin" svg={PIN} width={24} height={24} pixelRatio={2} />
      <GeoJSONSource
        id="markers"
        data={TEN_THOUSAND}
        cluster
        clusterRadius={50}
        clusterMaxZoom={14}
      >
        <CircleLayer
          id="clusters"
          source="markers"
          filter={HAS_COUNT}
          style={{
            circleColor: expr([
              "step",
              ["get", "point_count"],
              "#51bbd6",
              100,
              "#f1f075",
              750,
              "#f28cb1",
            ]),
            circleRadius: expr(["step", ["get", "point_count"], 16, 100, 24, 750, 32]),
            circleOpacity: 0.85,
            circleStrokeColor: "#ffffff",
            circleStrokeWidth: 1.5,
          }}
        />
        <SymbolLayer
          id="cluster-counts"
          source="markers"
          filter={HAS_COUNT}
          style={{
            textField: expr(["get", "point_count_abbreviated"]),
            textFont: ["Open Sans Regular"],
            textSize: 12,
            textColor: "#1f2937",
            textAllowOverlap: true,
          }}
        />
        <SymbolLayer
          id="unclustered-pins"
          source="markers"
          filter={NO_COUNT}
          style={{
            iconImage: "pin",
            iconSize: 1,
            iconAllowOverlap: true,
            iconAnchor: "bottom",
          }}
        />
      </GeoJSONSource>
    </Map>
  ),
};

